import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/half_to_int32_conversion.BH5jC7TG.png",e="/ascendc.github.io/pr/5487/assets/float_to_int16_conversion.DKmBbm75.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"关键特性说明","link":"/api/SIMD-API/basic_api/reg_vector_compute/key_features/key_features"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/key_features/key_features.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/key_features/key_features.md","outlineHeaders":[{"level":2,"title":"硬件循环（HardwareLoop）","slug":"硬件循环（HardwareLoop）","link":"#硬件循环（HardwareLoop）"},{"level":3,"title":"Hardware Loop编码规范","slug":"Hardware-Loop编码规范","link":"#Hardware-Loop编码规范"},{"level":2,"title":"指令双发优化","slug":"指令双发优化","link":"#指令双发优化"},{"level":3,"title":"指令双发","slug":"指令双发","link":"#指令双发"},{"level":3,"title":"合理拆分VF循环","slug":"合理拆分VF循环","link":"#合理拆分VF循环"},{"level":3,"title":"手动控制循环拆分","slug":"手动控制循环拆分","link":"#手动控制循环拆分"},{"level":2,"title":"VF融合","slug":"VF融合","link":"#VF融合"},{"level":2,"title":"数据搬运优化","slug":"数据搬运优化","link":"#数据搬运优化"},{"level":3,"title":"数据搬运启用分布模式","slug":"数据搬运启用分布模式","link":"#数据搬运启用分布模式"}],"lastUpdated":1787050286000}'),t={name:"api/SIMD-API/basic_api/reg_vector_compute/key_features/key_features.md"};function o(i,s,r,d,g,_){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>关键特性说明</h1><h2 id="硬件循环（HardwareLoop）">硬件循环（HardwareLoop）<a class="header-anchor" href="#硬件循环（HardwareLoop）">​</a></h2><p>Reg矢量计算架构中，Vector Function（VF）是实现高性能向量计算的核心载体。VF函数中可以包含最多四层嵌套循环，每层循环中还可以包含多个串行循环。VF循环对控制结构的支持有限，仅支持for循环和条件判断，不支持switch、do-while和while-do等其他控制结构。当VF函数中的循环满足Hardware Loop编码规范会被编译器优化为Hardware Loop，提升整体的编码性能，否则它的循环逻辑会由迭代变量和条件判断语句构成Software Loop，无法开启VF循环优化。</p><h3 id="Hardware-Loop编码规范">Hardware Loop编码规范<a class="header-anchor" href="#Hardware-Loop编码规范">​</a></h3><ul><li>Hardware Loop最多能支持的嵌套层数为4层；支持串行的Hardware Loop循环。</li><li>迭代变量类型<br>VF内所有Loop的迭代变量必须是uint16_t类型。</li><li>起始值与步长<br>循环起始值从0开始。<br>每次迭代的步长必须是递增1。</li><li>循环内不允许跳转指令，比如条件判断跳转，如if/else、三元运算符?:。<br>VF内if/else在Loop内会阻碍Hardware Loop的生成，编译器虽然会尽可能的做if/else消除优化，但是不做完全性保证。</li><li>一旦执行，循环计数/边界不允许被更改。</li><li>若要利用外层循环的计数作为循环边界，将外层循环计数器赋值给标量后作为内层循环边界。</li></ul><h2 id="指令双发优化">指令双发优化<a class="header-anchor" href="#指令双发优化">​</a></h2><p>Reg矢量计算接口指令单双发的情况请参考<a href="../../../../appendix/reg_vector_compute_interface_instruction_single_dual_issue_summary.html">Reg矢量计算接口指令单双发汇总</a>。</p><p>指令双发优化的性能优化详细内容请参考<a href="../../../../../guide/operator_practice/simd_operator_optimization/vector_compute/vf_optimization/dual_issue_optimization.html">算子实践参考-指令双发优化</a>。</p><h3 id="指令双发">指令双发<a class="header-anchor" href="#指令双发">​</a></h3><p>指令双发指的是处理器在同一个时钟周期内，能够同时发射两条指令到执行单元进行处理。</p><p>这种机制可以在不改变程序逻辑的前提下，提升处理器在单位时间内的指令处理效率，是实现指令级并行的重要基础之一。</p><h3 id="合理拆分VF循环">合理拆分VF循环<a class="header-anchor" href="#合理拆分VF循环">​</a></h3><p>VF并不是写的越长，把所有运算都放在一个for循环内就好，需要适当的搬出中间结果到Unified Buffer（UB），减少数据依赖。当指令数量过多，可能触发Icache Miss，即使循环间不存在依赖，也无法进行双发。当循环内包含同步，可以通过切分循环将同步外提减少同步次数。</p><h3 id="手动控制循环拆分">手动控制循环拆分<a class="header-anchor" href="#手动控制循环拆分">​</a></h3><p>如果循环内存在依赖关系过多的指令，指令无法并发执行，即无法启用双发特性。可以通过展开循环，提升指令双发能力，贴近硬件乱序执行的特性；减少指令因为寄存器资源未到位而产生的等待。</p><h2 id="VF融合">VF融合<a class="header-anchor" href="#VF融合">​</a></h2><p>VF融合是将代码中多个VF函数融合成一个VF函数，有效提升性能。VF融合特性是编译器优化特性，通过编译选项--cce-simd-vf-fusion=true开启，VF自动融合会借助Loop Fuse算法，将VF转换成Loop形态，然后将控制流等价（Control-Flow-Equivalent）的VF进行融合，最后将VF进行还原。编译器首先会做融合前的合法性检查，判断两个VF是否等价，Main侧中间代码是否能在VF内执行以及融合后是否可产生正收益。如果满足VF融合条件，编译器会自动执行VF融合优化，为保证融合后的VF执行逻辑与语义与融合前一致，会在原来两个VF之间保守地插入同步指令，编译器还会尝试外提、合并融合后的VF中的指令，对VF代码进行优化。融合策略是能融尽融，用户按照符合融合的合法性检查的模式进行编码，可以增加VF融合的机会。用户也可以参考融合原理手动进行融合优化。</p><p>VF融合的性能优化详细内容请参考<a href="../../../../../guide/operator_practice/simd_operator_optimization/vector_compute/vf_optimization/vf_fusion_optimization.html">算子实践参考-VF融合优化</a>。</p><h2 id="数据搬运优化">数据搬运优化<a class="header-anchor" href="#数据搬运优化">​</a></h2><p>Reg矢量计算API提供了下表所示多种搬运指令，合理选择搬运接口以及利用接口能力进行优化。连续非对齐场景优化的性能优化详细内容请参考<a href="../../../../../guide/operator_practice/simd_operator_optimization/vector_compute/vf_optimization/continuous_unaligned_optimization.html">算子实践参考-连续非对齐场景优化</a>。</p><table><thead><tr><th align="left">场景</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">连续对齐搬入(LoadAlign)</td><td align="left">能够实现数据从起始地址32B对齐的UB连续搬入RegTensor。</td></tr><tr><td align="left">非连续对齐搬入(LoadAlign)</td><td align="left">能够实现数据从起始地址32B对齐的UB非连续搬入RegTensor。</td></tr><tr><td align="left">连续非对齐搬入(LoadUnAlign)</td><td align="left">能够实现数据从起始地址非32B对齐的UB连续搬入RegTensor。</td></tr><tr><td align="left">MaskReg搬入(LoadAlign)</td><td align="left">能够实现数据从起始地址32B对齐的UB连续搬入MaskReg。</td></tr><tr><td align="left">MaskReg搬入(MaskGenWithRegTensor)</td><td align="left">能够实现数据从RegTensor搬入MaskReg。</td></tr><tr><td align="left">离散搬入(Gather)</td><td align="left">能够根据索引值index将源操作数按元素收集到目的操作数RegTensor中。</td></tr><tr><td align="left">离散搬入(GatherB)</td><td align="left">能够根据索引值index将源操作数按DataBlock（32B）收集到目的操作数RegTensor中。</td></tr></tbody></table><h3 id="数据搬运启用分布模式">数据搬运启用分布模式<a class="header-anchor" href="#数据搬运启用分布模式">​</a></h3><ul><li><p>连续对齐搬入(LoadAlign)</p><p>如图<a href="#fig1">half转int32_t类型转换过程</a>，将UB地址xAddr上数据量为VL/2的half类型元素通过LoadAlign（分布模式为DIST_UNPACK_B16）搬入xReg，调用Cast将half转为int32_t，写入yReg，最后通过StoreAlign（分布模式为DIST_NORM）搬出至UB地址yAddr。</p><p><strong>图1</strong> half转int32_t类型转换过程<a id="fig1"></a></p><p><img src="'+c+`" alt title="half转int32_t类型转换过程"></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 位宽小转大，以half-&gt;int32_t为例 </span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CastTrait</span><span class="w"> </span><span class="n">castTrait</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegLayout</span><span class="o">::</span><span class="n">ZERO</span><span class="p">,</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">SatMode</span><span class="o">::</span><span class="n">UNKNOWN</span><span class="p">,</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskMergeMode</span><span class="o">::</span><span class="n">ZEROING</span><span class="p">,</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">RoundMode</span><span class="o">::</span><span class="n">CAST_FLOOR</span>
<span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">PostLiteral</span><span class="o">::</span><span class="n">POST_MODE_UPDATE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadDist</span><span class="o">::</span><span class="n">DIST_UNPACK_B16</span><span class="o">&gt;</span><span class="p">(</span><span class="n">xReg</span><span class="p">,</span><span class="w"> </span><span class="n">xAddr</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span><span class="w"> </span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">castTrait</span><span class="o">&gt;</span><span class="p">(</span><span class="n">yReg</span><span class="p">,</span><span class="w"> </span><span class="n">xReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">PostLiteral</span><span class="o">::</span><span class="n">POST_MODE_UPDATE</span><span class="o">&gt;</span><span class="p">(</span><span class="n">yAddr</span><span class="p">,</span><span class="w"> </span><span class="n">yReg</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div></li><li><p>连续对齐搬出(StoreAlign)</p><p>如图<a href="#fig2">float转int16_t类型转换过程</a>，将UB地址xAddr上数据量为VL的float类型元素通过LoadAlign（分布模式为DIST_NORM）搬入xReg，调用Cast将float转为int16_t，写入yReg，最后通过StoreAlign（分布模式为DIST_PACK_B32）搬出至UB地址yAddr。</p><p><strong>图2</strong> float转int16_t类型转换过程<a id="fig2"></a></p><p><img src="`+e+`" alt title="float转int16_t类型转换过程"></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 位宽大转小，以float-&gt;int16_t为例 </span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">PostLiteral</span><span class="o">::</span><span class="n">POST_MODE_UPDATE</span><span class="o">&gt;</span><span class="p">(</span><span class="n">xReg</span><span class="p">,</span><span class="w"> </span><span class="n">xAddr</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span><span class="w">  </span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Cast</span><span class="o">&lt;</span><span class="kt">int16_t</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">castTrait</span><span class="o">&gt;</span><span class="p">(</span><span class="n">yReg</span><span class="p">,</span><span class="w"> </span><span class="n">xReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span><span class="w"> </span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="o">&lt;</span><span class="kt">int16_t</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">PostLiteral</span><span class="o">::</span><span class="n">POST_MODE_UPDATE</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreDist</span><span class="o">::</span><span class="n">DIST_PACK_B32</span><span class="o">&gt;</span><span class="p">(</span><span class="n">yAddr</span><span class="p">,</span><span class="w"> </span><span class="n">yReg</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div></li></ul></article></div>`,1)])])}const A=a(t,[["render",o]]);export{f as __pageData,A as default};
